function prepareRequests({ prompt, system, primary_model, fallback_model }) {
  if (typeof prompt !== "string" || !prompt.trim() || prompt.length > 24000) {
    throw new Error("Provide a prompt of up to 24,000 characters.");
  }
  const instructions = system ?? "You are a concise, helpful assistant. Answer in plain text.";
  if (typeof instructions !== "string" || instructions.length > 8000) {
    throw new Error("Provide a system instruction of up to 8,000 characters.");
  }
  const models = [primary_model, fallback_model];
  if (
    models.some(
      (id) =>
        typeof id !== "string" ||
        !id.trim() ||
        id !== id.trim() ||
        id.length > 256 ||
        ["YOUR_DAOXE_MODEL_ID", "YOUR_DAOXE_FALLBACK_MODEL_ID"].includes(id),
    ) ||
    primary_model === fallback_model
  ) {
    throw new Error("Set two distinct model IDs from your DaoXE group.");
  }
  const messages = [
    { role: "system", content: instructions },
    { role: "user", content: prompt },
  ];
  return {
    primary: { model: primary_model, messages, stream: false },
    fallback: { model: fallback_model, messages, stream: false },
  };
}

return {
  json: prepareRequests({
    prompt: "Suggest three titles for a guide to indoor herb gardening.",
    system: "You are a concise, helpful assistant. Answer in plain text.",
    primary_model: "YOUR_DAOXE_MODEL_ID",
    fallback_model: "YOUR_DAOXE_FALLBACK_MODEL_ID",
  }),
};

function inspectReply(status, body, via) {
  if (status === 408 || status === 429 || (status >= 500 && status <= 599)) {
    return { temporaryFailure: "HTTP " + status };
  }
  if (status === 401 || status === 403) {
    throw new Error(
      "DaoXE rejected the " +
        via +
        " request (HTTP " +
        status +
        "). Check the shared key, model permissions and account balance.",
    );
  }
  if (status !== 200) {
    throw new Error("DaoXE rejected the " + via + " request (HTTP " + status + ").");
  }
  let response;
  try {
    response = JSON.parse(body);
  } catch {
    throw new Error("DaoXE returned invalid JSON for the " + via + " request.");
  }
  const choice = response?.choices?.[0];
  const answer = choice?.message?.content;
  if (
    response?.error ||
    typeof answer !== "string" ||
    !answer.trim() ||
    (choice.finish_reason && choice.finish_reason !== "stop")
  ) {
    throw new Error("DaoXE returned no complete text answer for the " + via + " request.");
  }
  const served_model =
    typeof response.model === "string" && response.model.trim() ? response.model : null;
  return { answer, served_model, via };
}

function n8nReply(http, via) {
  if (Number.isInteger(http.statusCode)) return inspectReply(http.statusCode, http.body, via);
  const error = http.error;
  const transportCode = [
    "ETIMEDOUT",
    "ESOCKETTIMEDOUT",
    "ECONNABORTED",
    "ECONNRESET",
    "ECONNREFUSED",
    "EAI_AGAIN",
    "ENOTFOUND",
    "EPIPE",
    "ERR_NETWORK",
  ];
  if (transportCode.includes(error?.code ?? error?.cause?.code))
    return { temporaryFailure: "transport result unknown" };
  throw new Error(
    "DaoXE could not process the " + via + " request. Check the HTTP node and its credential.",
  );
}

return { json: n8nReply($json, "primary") };

